  'tpl.warnUnclosedTag': 'ఈ HTMLలో కొన్ని ట్యాగ్‌లు సరిగ్గా మూయబడినట్లు కనిపించడం లేదు — ఇది ఈమెయిల్‌లోని కొన్ని భాగాలలో లేఅవుట్‌ను విచ్ఛిన్నం చేయవచ్చు.',
