  'auth.asideText': 'మీ జాబితాను ఇంపోర్ట్ చేయండి, ఈమెయిల్‌ను ఒకసారి రాయండి, సురక్షిత బ్యాచ్‌లలో పంపండి, మరియు ఓపెన్‌లు మరియు క్లిక్‌లు రావడం చూడండి.',
  'auth.point1': 'ఒకే క్లిక్‌లో Gmail లేదా Outlook కనెక్ట్ చేయండి — SMTP సెట్టింగ్‌లు వెతకాల్సిన అవసరం లేదు.',
  'auth.point2': 'ఒక Excel ఫైల్‌ను అప్‌లోడ్ చేయండి మరియు మేము దాన్ని మీ కోసం క్లీన్ చేసి, తనిఖీ చేసి, డి-డూప్లికేట్ చేస్తాము.',
  'auth.point3': 'మీ ప్రొవైడర్ పరిమితులను గౌరవించే సురక్షిత బ్యాచ్‌లలో పంపండి.',
  'auth.point4': 'ఓపెన్‌లు, క్లిక్‌లు, బౌన్స్‌లు మరియు సబ్‌స్క్రిప్షన్ రద్దులను అవి జరిగినప్పుడు చూడండి.',
  'auth.setTitle': 'మీ పాస్‌వర్డ్‌ను ఎంచుకోండి',
