  'users.pwdNote': 'ఇప్పటికే ఉన్న పాస్‌వర్డ్‌ను ఎవరూ చూడలేరు — కేవలం స్క్రాంబుల్ చేసిన కాపీ మాత్రమే నిల్వ చేయబడుతుంది. సూపర్ అడ్మిన్ కొత్తదాన్ని సెట్ చేయవచ్చు, లేదా వ్యక్తి స్వయంగా ఎంచుకోవడానికి రీసెట్ లింక్‌ను పంపవచ్చు.',
