  'nav.systemEmails': 'సిస్టమ్ ఈమెయిల్స్',
  'sysmail.title': 'సిస్టమ్ ఈమెయిల్స్',
  'sysmail.subtitle': 'యాప్ స్వయంగా పంపే ఈమెయిల్స్ — ఆహ్వానాలు, పాస్‌వర్డ్ రీసెట్‌లు, హెచ్చరికలు మరియు రిపోర్ట్‌లు.',
  'sysmail.intro': 'ఇవి క్యాంపెయిన్‌లు కావు. ప్రతి ఒక్కటి ఒక ఈవెంట్ ద్వారా ప్రేరేపించబడుతుంది, మరియు డిజైన్ ఇప్పటికే రాయబడింది. బ్యాకెండ్ నిర్మించబడినప్పుడు, ప్రతి ఈవెంట్‌కు కేవలం ఒక లైన్ మాత్రమే అవసరం — సబ్జెక్ట్ మరియు HTML ఇక్కడ నుండి వస్తాయి.',
  'sysmail.list': 'ప్రతి సిస్టమ్ ఈమెయిల్',
  'sysmail.listSub': 'దాన్ని ప్రివ్యూ చేయడానికి లేదా ఎడిట్ చేయడానికి ఒకదాన్ని ఎంచుకోండి',
  'sysmail.group': 'గ్రూప్',
  'sysmail.language': 'భాష',
  'sysmail.fallbackNote': 'ఇంకా {language} వెర్షన్ సేవ్ చేయబడలేదు — కింద ఇంగ్లీష్ కంటెంట్‌ను చూపిస్తోంది. ఒకదాన్ని సృష్టించడానికి ఎడిట్ చేసి సేవ్ చేయండి.',
