  'send.estimateQuotaLimited': '≈ {days} రోజులు — {account} రోజుకు {limit} మాత్రమే పంపగలదు, కాబట్టి పంపడం ప్రతిరోజూ స్వయంచాలకంగా పాజ్ అయి తిరిగి మొదలవుతుంది. బ్యాచ్‌ల మధ్య నిజమైన వేచి ఉండే సమయం సుమారు {duration}.',
  'send.estimateSampleLabel': 'ఎంత మంది గ్రహీతలకు అంచనా?',
  'send.estimateAccountNote': 'ఇది ఒక స్థూల అంచనా (బ్యాచ్ సైజ్ × వేచి ఉండే సమయం మాత్రమే). నిజమైన సంఖ్య ఏ ఈమెయిల్ ఖాతా దీన్ని పంపుతుంది మరియు ఆ ఖాతా రోజువారీ పరిమితిపై ఆధారపడి ఉంటుంది — ఖచ్చితమైన అంచనా కోసం క్యాంపెయిన్ విజార్డ్‌లో నిజమైన ప్రేక్షకులను ఎంచుకోండి.',
  'send.openTracking': 'ఓపెన్ ట్రాకింగ్',
  'send.openTrackingDesc': 'ఓపెన్‌లను అంచనా వేయగలిగేలా ఒక చిన్న అదృశ్య చిత్రాన్ని జోడిస్తుంది. ఫలితాలు ఒక అంచనా — కొన్ని మెయిల్ యాప్‌లు చిత్రాన్ని బ్లాక్ చేస్తాయి, మరియు ప్రైవసీ ప్రాక్సీలు ఎప్పుడూ జరగని ఓపెన్‌ను లెక్కించవచ్చు.',
  'send.clickTracking': 'క్లిక్ ట్రాకింగ్',
  'send.clickTrackingDesc': 'క్లిక్‌లను లెక్కించగలిగేలా ఈ క్యాంపెయిన్‌లో లింక్‌లను తిరిగి రాస్తుంది. డిఫాల్ట్‌గా ఆఫ్‌లో ఉంటుంది — మీరు దీన్ని ప్రతి క్యాంపెయిన్‌కు ఆన్ చేస్తారు.',
  'send.subscribeButton': 'సబ్‌స్క్రయిబ్ బటన్',
  'send.subscribeTitle': 'ఈ ఈమెయిల్‌కు సబ్‌స్క్రయిబ్ బటన్‌ను జోడించండి',
  'send.subscribeDesc': 'కొన్ని ఈమెయిల్స్ ఇంకా మీ జాబితాలో లేని వ్యక్తులకు వెళ్తాయి. ఒక సబ్‌స్క్రయిబ్ బటన్ వారు మరింత అడగడానికి అనుమతిస్తుంది. దాన్ని నొక్కేవారు మీ సబ్‌స్క్రైబర్‌ల పేజీపై దిగుతారు, వారి పక్కనే ఈ క్యాంపెయిన్ పేరుతో — కాబట్టి వారు ఎక్కడ నుండి వచ్చారో మీకు ఎల్లప్పుడూ తెలుస్తుంది.',
  'send.subscribeNote': 'మీ HTMLలో ఎక్కడైనా {{subscribe_url}} పెట్టండి మరియు అది సబ్‌స్క్రయిబ్ లింక్‌గా మారుతుంది. మీరు దాన్ని వదిలేస్తే, మేము మీ కోసం ఫుటర్‌కు పైన ఒక చిన్న బటన్‌ను జోడిస్తాము.',
  'send.whenTitle': 'ఇది ఎప్పుడు పంపాలి?',
  'send.now': 'ఇప్పుడే పంపండి',
  'send.nowDesc': 'మీరు నిర్ధారించిన వెంటనే పంపడం మొదలవుతుంది.',
  'send.later': 'తర్వాత కోసం షెడ్యూల్ చేయండి',
  'send.laterDesc': 'ఒక తేదీ మరియు సమయాన్ని ఎంచుకోండి. మేము మీ కోసం దాన్ని క్యూలో పెడతాము.',
  'send.dateTime': 'తేదీ మరియు సమయం',
  'send.queueNote': 'పంపడం మా సర్వర్ క్యూలో నడుస్తుంది. మీరు ఈ ట్యాబ్‌ను లేదా మీ ల్యాప్‌టాప్‌ను మూసివేయవచ్చు — క్యాంపెయిన్ కొనసాగుతూనే ఉంటుంది, మరియు మీరు దాన్ని ఎప్పుడైనా పాజ్ చేయవచ్చు.',

