  'set.emailLanguage': 'ఇష్టపడే ఈమెయిల్ భాష',
  'set.emailLanguageHelp': 'మీకు వచ్చే స్వయంచాలక ఈమెయిల్స్ — పాస్‌వర్డ్ రీసెట్‌లు, ఆహ్వానాలు — ఈ భాషలో వస్తాయి. ఇది పైన ఉన్న భాష ట్యాబ్ నుండి వేరుగా ఉంటుంది, అది కేవలం మీరు స్క్రీన్‌పై చూసేదాన్ని మాత్రమే మారుస్తుంది.',
