  'set.addLanguageNote': 'మరో భాష కావాలా? src/i18n/locales/en.jsను కాపీ చేసి, విలువలను అనువదించి, src/i18n/languages.jsకు ఒక లైన్ జోడించండి. మీరు వదిలేసే ఏ కీ అయినా ఇంగ్లీష్‌కు ఫాల్‌బ్యాక్ అవుతుంది, కాబట్టి సగం పూర్తయిన అనువాదం ఎప్పుడూ ఒక స్క్రీన్‌ను విరగ్గొట్టదు.',
