  'set.retryDesc': 'ఒక తాత్కాలిక ప్రొవైడర్ ఎర్రర్ 15 నిమిషాల తర్వాత మళ్ళీ ప్రయత్నించబడుతుంది. హార్డ్ బౌన్స్‌లు ఎప్పుడూ మళ్ళీ ప్రయత్నించబడవు.',
  'set.quietTitle': 'నిశ్శబ్ద గంటలను గౌరవించండి (రాత్రి 9 – ఉదయం 8)',
  'set.quietDesc': 'క్యూలో ఉన్న ఈమెయిల్స్ గ్రహీత టైమ్ జోన్‌లో ఉదయం వరకు వేచి ఉంటాయి.',
  'set.sendingNote': 'మీరు ఇక్కడ సెట్ చేసే బ్యాచ్ సైజ్ మరియు ఆలస్యం ప్రతి కొత్త క్యాంపెయిన్‌కు ప్రారంభ బిందువుగా మారతాయి — మీరు ఇంకా వాటిని విజార్డ్‌లో ప్రతి క్యాంపెయిన్‌కు మార్చవచ్చు. మళ్ళీ ప్రయత్నించడం ప్రతి క్యాంపెయిన్‌కు స్వయంచాలకంగా వర్తించబడుతుంది. నిశ్శబ్ద గంటలు ఒక ప్రాధాన్యతగా సేవ్ చేయబడతాయి; పంపే ఇంజిన్ దానిపై ఇంకా చర్య తీసుకోదు.',
  'set.trackingTitle': 'ట్రాకింగ్ సెట్టింగ్‌లు',
  'set.trackingSub': 'మేము ఏం రికార్డ్ చేస్తాము, మరియు ఏం చేయము',
  'set.openDefaultTitle': 'డిఫాల్ట్‌గా ఓపెన్ ట్రాకింగ్ ఆన్‌లో ఉంటుంది',
  'set.openDefaultDesc': 'ఓపెన్‌లను అంచనా వేయడానికి ఒక అదృశ్య చిత్రాన్ని జోడిస్తుంది. మీరు దీన్ని ఇంకా ప్రతి క్యాంపెయిన్‌కు ఆఫ్ చేయవచ్చు.',
  'set.clickDefaultTitle': 'డిఫాల్ట్‌గా క్లిక్ ట్రాకింగ్ ఆన్‌లో ఉంటుంది',
  'set.clickDefaultDesc': 'క్లిక్‌లను లెక్కించగలిగేలా లింక్‌లను తిరిగి రాస్తుంది. మీకు ప్లెయిన్ లింక్‌లు ఇష్టమైతే దీన్ని ఆఫ్ చేయండి.',
  'set.deviceTitle': 'పరికర రకాన్ని రికార్డ్ చేయండి',
  'set.deviceDesc': 'రా బ్రౌజర్/మెయిల్-యాప్ స్ట్రింగ్ ఇప్పటికే ప్రతి ఓపెన్ మరియు క్లిక్‌తో ఎల్లప్పుడూ నిల్వ చేయబడుతుంది — ఈ స్విచ్ దాన్ని ఇంకా మార్చదు.',
  'set.locationTitle': 'సుమారు స్థానాన్ని రికార్డ్ చేయండి',
  'set.locationDesc': 'IP చిరునామా ఇప్పటికే ఎల్లప్పుడూ నిల్వ చేయబడుతుంది — ఈ స్విచ్ ఇంకా ఒక దేశం పేరును ఆన్ లేదా ఆఫ్ చేయదు, ఎందుకంటే ఇంకా ఏ లుకప్ దశ లేదు.',
  'set.openEstimateNote': 'ఓపెన్ కౌంట్‌లు ఎల్లప్పుడూ ఒక అంచనా. చిత్రం బ్లాకింగ్ నిజమైన ఓపెన్‌లను దాచుతుంది, మరియు ప్రైవసీ ప్రాక్సీలు ఎప్పుడూ జరగని ఓపెన్‌లను సృష్టిస్తాయి. ఈ కారణంగా మేము ప్రతి ఓపెన్‌ను "Open detected"గా లేబుల్ చేస్తాము.',
  'set.trackingNote': 'ఓపెన్ మరియు క్లిక్ ట్రాకింగ్ డిఫాల్ట్‌లు నిజంగా ప్రతి కొత్త క్యాంపెయిన్‌కు వర్తిస్తాయి (మీరు ఇంకా ప్రతి క్యాంపెయిన్‌కు ఓవర్‌రైడ్ చేయవచ్చు). పరికరం మరియు స్థానం ప్రస్తుతానికి కేవలం ఒక ప్రాధాన్యతగా మాత్రమే సేవ్ చేయబడతాయి — రా యూజర్-ఏజెంట్ మరియు IP ఈ రెండు స్విచ్‌లతో సంబంధం లేకుండా ప్రతి ఓపెన్‌పై నమోదు చేయబడతాయి.',
  'set.templateOptions': 'టెంప్లేట్ ఎంపికలు',
  'set.templateOptionsSub': 'ఏ టెంప్లేట్ సృష్టి పద్ధతులు అందుబాటులో ఉన్నాయో ఎంచుకోండి',
  'set.templateOptionsNote': 'ఒక పద్ధతిని ఆఫ్ చేయడం కేవలం దాన్ని దాచుతుంది మాత్రమే — కొత్త టెంప్లేట్‌లు, మరియు అవి జాబితా చేసే ప్రతిచోటా — ఏదీ ఎప్పుడూ తొలగించబడదు. ఆ రకం యొక్క ఇప్పటికే ఉన్న టెంప్లేట్‌లు సురక్షితంగా ఉంటాయి మరియు మీరు దాన్ని తిరిగి ఆన్ చేసిన క్షణం మళ్ళీ కనిపిస్తాయి.',
  'set.tplSrcCustomTitle': 'కస్టమ్ ఎడిటర్',
  'set.tplSrcCustomDesc': 'డిజైన్ + కోడ్ ఎడిటర్ ఉపయోగించి టెంప్లేట్‌లను సృష్టించండి.',
  'set.tplSrcUploadTitle': 'HTML అప్‌లోడ్',
  'set.tplSrcUploadDesc': 'మీ స్వంత HTML ఈమెయిల్ టెంప్లేట్‌ను అప్‌లోడ్ చేయండి.',
