  'set.dedupeTitle': 'ఇంపోర్ట్‌పై డూప్లికేట్‌లను తీసివేయండి',
  'set.dedupeDesc': 'మొదటి కాపీని ఉంచి మిగతావాటిని దాటవేస్తుంది. సిఫార్సు చేయబడింది.',
  'set.consentTitle': 'ఒక సమ్మతి మూలం అవసరం',
  'set.consentDesc': 'ప్రతి ఇంపోర్ట్ చేసిన కాంటాక్ట్ వారి అనుమతి ఎక్కడ నుండి వచ్చిందో చెప్పాలి.',
  'set.customFields': 'కస్టమ్ ఫీల్డ్‌లు',
  'set.customFieldsHelp': 'కామాలతో వేరు చేయండి. ప్రతి ఒక్కటి ఒక వేరియబుల్‌గా మారుతుంది, ఉదా. {{city}}.',
  'set.contactsNote': 'ఇంపోర్ట్‌పై డూప్లికేట్‌లను తీసివేయడం ఇప్పటికే ఎల్లప్పుడూ జరుగుతుంది — ఇది ఐచ్ఛికం కాదు. మిగతా రెండు ఒక ప్రాధాన్యతగా సేవ్ చేయబడతాయి; సమ్మతి ఇంపోర్ట్ స్క్రీన్ ద్వారా ఇంకా అవసరం లేదు, మరియు కస్టమ్ ఫీల్డ్‌లు టెంప్లేట్‌లలో మెర్జ్ వేరియబుల్స్‌గా ఇంకా అందించబడలేదు.',
  'set.unsubTitle': 'సబ్‌స్క్రిప్షన్ రద్దు సెట్టింగ్‌లు',
