  'set.unsubLinkText': 'సబ్‌స్క్రిప్షన్ రద్దు లింక్ టెక్స్ట్',
  'set.unsubMessage': 'సబ్‌స్క్రిప్షన్ రద్దు చేసిన తర్వాత చూపించే సందేశం',
  'set.oneClickTitle': 'వన్-క్లిక్ సబ్‌స్క్రిప్షన్ రద్దు హెడర్',
  'set.oneClickDesc': 'List-Unsubscribe హెడర్‌ను జోడిస్తుంది. Gmail మరియు Outlook ఇప్పుడు బల్క్ పంపేవారి నుండి దీన్ని ఆశిస్తాయి.',
  'set.unsubGlobalTitle': 'సబ్‌స్క్రిప్షన్ రద్దులను గ్లోబల్‌గా వర్తింపజేయండి',
  'set.unsubGlobalDesc': 'ఆఫ్ (సిఫార్సు చేయబడింది): ఒక పంపే ఖాతా నుండి సబ్‌స్క్రిప్షన్ రద్దు చేయడం కేవలం ఆ ఖాతా నుండి భవిష్యత్తు ఈమెయిల్స్‌ను మాత్రమే బ్లాక్ చేస్తుంది — ఈ వర్క్‌స్పేస్‌లోని ఇతర ఖాతాలు వారికి ఇంకా మెయిల్ చేయగలవు. ఆన్: ఒక సబ్‌స్క్రిప్షన్ రద్దు ప్రతి పంపే ఖాతాను బ్లాక్ చేస్తుంది.',
  'set.unsubNote': 'సబ్‌స్క్రిప్షన్ రద్దు చేసిన వ్యక్తులు ఆ పంపే ఖాతా కోసం సప్రెషన్ జాబితాలోకి వెళ్తారు మరియు ఆ ఖాతా యొక్క భవిష్యత్తు క్యాంపెయిన్‌ల నుండి స్వయంచాలకంగా తీసివేయబడతారు.',
