  'set.webhooksNoCodeText': 'Zapier, Make.com లేదా Pabbly Connect తెరవండి, ఒక కొత్త ఆటోమేషన్‌ను మొదలుపెట్టండి, మరియు "Webhooks" లేదా "Catch Hook" అనే ట్రిగ్గర్‌ను ఎంచుకోండి. అది మీకు ఒక వెబ్ చిరునామాను ఇస్తుంది — ఆ చిరునామాను కింద పేస్ట్ చేయండి, దీన్ని ఆన్ చేయండి, మరియు సేవ్ నొక్కండి. అదే మొత్తం సెటప్.',
